package br.com.peladaleague.app;
import android.view.View;
import android.widget.*;
import java.util.*;

final class EventForm extends Screen {
    EventForm(MainActivity a){super(a);}
    private void set(Spinner spinner,List<String> values){ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,values);spinner.setAdapter(adapter);}
    private AdapterView.OnItemSelectedListener listen(Runnable r){return new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){r.run();}public void onNothingSelected(AdapterView<?> p){}};}
    void goal(DemoDb.Goal edit){if(!a.canRecord())return;DemoDb.Game m=db.game(a.gameId);Forms f=new Forms(a);LinearLayout form=f.form();Spinner kind=f.spinner(form,"Tipo de gol",List.of("Gol","Gol contra")),side=f.spinner(form,"Equipe que ganha o ponto",List.of(m.a,m.b));Spinner scorer=f.spinner(form,"Autor do lance (escalado)",new ArrayList<>());EditText minute=f.field(form,"Minuto (0 a 240)",edit==null?"":String.valueOf(edit.minute),true);Spinner assist=f.spinner(form,"Assistência",List.of("Sem assistência"));
        List<DemoDb.Player> scorers=new ArrayList<>(),assists=new ArrayList<>();if(edit!=null){kind.setSelection(edit.ownGoal?1:0);side.setSelection(edit.team);}
        Runnable populate=()->{int team=side.getSelectedItemPosition();boolean own=kind.getSelectedItemPosition()==1;scorers.clear();scorers.addAll(db.roster(m.id,own?1-team:team));set(scorer,scorers.stream().map(p->p.name).collect(java.util.stream.Collectors.toList()));if(edit!=null)for(int i=0;i<scorers.size();i++)if(scorers.get(i).id==edit.playerId)scorer.setSelection(i);};
        Runnable populateAssist=()->{assists.clear();List<String> labels=new ArrayList<>();labels.add("Sem assistência");boolean own=kind.getSelectedItemPosition()==1;long author=scorers.isEmpty()?0:scorers.get(Math.max(0,scorer.getSelectedItemPosition())).id;if(!own)for(DemoDb.Player p:db.roster(m.id,side.getSelectedItemPosition()))if(p.id!=author){assists.add(p);labels.add(p.name);}set(assist,labels);assist.setEnabled(!own);if(edit!=null)for(int i=0;i<assists.size();i++)if(assists.get(i).id==edit.assistId)assist.setSelection(i+1);};
        side.setOnItemSelectedListener(listen(populate));kind.setOnItemSelectedListener(listen(populate));scorer.setOnItemSelectedListener(listen(populateAssist));populate.run();populateAssist.run();
        f.dialog(edit==null?"Adicionar gol":"Editar gol",form,"Salvar",()->{if(scorers.isEmpty())throw new IllegalArgumentException("Nenhum jogador escalado nesta equipe.");long author=scorers.get(scorer.getSelectedItemPosition()).id;boolean own=kind.getSelectedItemPosition()==1;long pass=own||assist.getSelectedItemPosition()==0?0:assists.get(assist.getSelectedItemPosition()-1).id;int time=Integer.parseInt(minute.getText().toString());if(edit==null)db.addGoal(m.id,author,side.getSelectedItemPosition(),time,pass,own);else db.editGoal(edit.id,m.id,author,side.getSelectedItemPosition(),time,pass,own);a.matchTab=0;a.highlightScore=true;a.refresh();});
    }
    void card(DemoDb.Card edit){if(!a.canRecord())return;DemoDb.Game m=db.game(a.gameId);Forms f=new Forms(a);LinearLayout form=f.form();Spinner side=f.spinner(form,"Equipe",List.of(m.a,m.b)),player=f.spinner(form,"Jogador escalado",new ArrayList<>()),color=f.spinner(form,"Cartão",List.of("Amarelo","Vermelho"));EditText minute=f.field(form,"Minuto (0 a 240)",edit==null?"":String.valueOf(edit.minute),true);List<DemoDb.Player> roster=new ArrayList<>();if(edit!=null){side.setSelection(edit.team);color.setSelection(edit.color.equals("RED")?1:0);}
        Runnable populate=()->{roster.clear();roster.addAll(db.roster(m.id,side.getSelectedItemPosition()));set(player,roster.stream().map(p->p.name).collect(java.util.stream.Collectors.toList()));if(edit!=null)for(int i=0;i<roster.size();i++)if(roster.get(i).id==edit.playerId)player.setSelection(i);};side.setOnItemSelectedListener(listen(populate));populate.run();f.dialog(edit==null?"Registrar cartão":"Editar cartão",form,"Salvar",()->{if(roster.isEmpty())throw new IllegalArgumentException("Nenhum jogador escalado nesta equipe.");long id=roster.get(player.getSelectedItemPosition()).id;int time=Integer.parseInt(minute.getText().toString());String c=color.getSelectedItemPosition()==0?"YELLOW":"RED";if(edit==null)db.addCard(m.id,id,side.getSelectedItemPosition(),c,time);else db.editCard(edit.id,m.id,id,side.getSelectedItemPosition(),c,time);a.matchTab=1;a.refresh();});
    }
}
